const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Pacific Palisades location
  const palisades = ee.Geometry.Point([-118.53, 34.05]);
  const region = palisades.buffer(5000); // 5km buffer

  // 2. Define date ranges
  const date1_start = '2025-01-09';
  const date1_end = '2025-01-10';
  const date2_start = '2025-01-12';
  const date2_end = '2025-01-13';

  // 3. Load Sentinel-5P NO2 data
  const s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2');

  // Filter for Jan 9, 2025
  let col1 = s5p
    .filterDate(date1_start, date1_end)
    .filterBounds(region)
    .select(['tropospheric_NO2_column_number_density', 'qa_value']);

  // Filter for Jan 12, 2025
  let col2 = s5p
    .filterDate(date2_start, date2_end)
    .filterBounds(region)
    .select(['tropospheric_NO2_column_number_density', 'qa_value']);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Jan 9 images: ${size1}`);
  console.log(`Jan 12 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Apply quality mask and get mean NO2
  function maskQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.select('tropospheric_NO2_column_number_density').updateMask(mask);
  }

  const img1 = col1.map(maskQuality).mean();
  const img2 = col2.map(maskQuality).mean();

  // 5. Calculate statistics
  const stats1 = await img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const no2_jan9 = stats1.tropospheric_NO2_column_number_density_mean;
  const count1 = stats1.tropospheric_NO2_column_number_density_count;
  const no2_jan12 = stats2.tropospheric_NO2_column_number_density_mean;
  const count2 = stats2.tropospheric_NO2_column_number_density_count;

  console.log(`Jan 9: NO2=${no2_jan9}, Pixels=${count1}`);
  console.log(`Jan 12: NO2=${no2_jan12}, Pixels=${count2}`);

  // 6. Validation
  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (no2_jan9 === null || no2_jan12 === null || 
      isNaN(no2_jan9) || isNaN(no2_jan12)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and answer
  if (no2_jan9 > no2_jan12) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
